/* ENG3 G1 instrument: LD_PRELOAD counter of CUDA runtime API calls (generated by an inline Python loop recorded in
 * artifacts/eng3/LEDGER.md). Every libcudart entry point the engine module imports (nm -D --undefined-only), except the
 * load-time fat-binary registration calls, is wrapped: the wrapper counts the call and forwards all argument registers
 * and two stack slots to the real function (x86-64 SysV; none of these functions takes a float by value, and the file
 * is compiled with -mgeneral-regs-only). eng3_cudart_calls() returns the total, eng3_cudart_count(i) / eng3_cudart_name(i)
 * the per-function counts. Prior art: LD_PRELOAD interposition with dlsym(RTLD_NEXT) (ltrace-style call tracing,
 * glibc ld.so); taken as is. Ours: the function list and the counting use. */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdint.h>
typedef uint64_t u64;
typedef u64 (*fn8)(u64,u64,u64,u64,u64,u64,u64,u64);
static volatile unsigned long g_total = 0;
static const char* g_names[32] = {"cudaDeviceGetDefaultMemPool","cudaDeviceSynchronize","cudaEventCreate","cudaEventCreateWithFlags","cudaEventDestroy","cudaEventElapsedTime","cudaEventRecord","cudaEventSynchronize","cudaFree","cudaFreeAsync","cudaFuncSetAttribute","cudaGetDevice","cudaGetErrorName","cudaGetErrorString","cudaGetLastError","cudaLaunchKernel","cudaMalloc","cudaMallocAsync","cudaMemcpy","cudaMemGetInfo","cudaMemPoolGetAttribute","cudaMemPoolSetAttribute","cudaMemPoolTrimTo","cudaMemset","cudaMemsetAsync","cudaPeekAtLastError","cudaPointerGetAttributes","__cudaPopCallConfiguration","__cudaPushCallConfiguration","cudaSetDevice","cudaStreamSynchronize","cudaStreamWaitEvent"};
static volatile unsigned long g_counts[32];
/* libcudart is a dependency of the RTLD_LOCAL-loaded Python extension, so it is not in the global scope and
 * dlsym(RTLD_NEXT) cannot see it: resolve from the already-loaded libcudart.so.12 handle instead (RTLD_NOLOAD). */
static void* real_sym(const char* n) {
  void* p = dlsym(RTLD_NEXT, n);
  if (p) return p;
  void* h = dlopen("libcudart.so.12", RTLD_LAZY | RTLD_NOLOAD);
  return h ? dlsym(h, n) : 0;
}
static fn8 g_real[32];
unsigned long eng3_cudart_calls(void) { return g_total; }
unsigned long eng3_cudart_count(int i) { return (i >= 0 && i < 32) ? g_counts[i] : 0; }
const char* eng3_cudart_name(int i) { return (i >= 0 && i < 32) ? g_names[i] : 0; }
int eng3_cudart_n(void) { return 32; }
